                : 'right-3 bottom-3 left-3 mx-auto max-h-[82vh] max-w-160 rounded-tile',
            )}
          >
            {!isRight && (
              <div className="mx-auto mt-3 h-1.5 w-10 rounded-full bg-[#E8EBF0]" />
