import * as React from 'react'
import {
  columnFilteringFeature,
  columnVisibilityFeature,
  createColumnHelper,
  createExpandedRowModel,
  createFilteredRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  filterFn_arrIncludesSome,
  filterFn_equals,
  filterFn_equalsString,
  filterFn_includesString,
  filterFn_inNumberRange,
  globalFilteringFeature,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_basic,
  sortFn_datetime,
  sortFn_text,
  tableFeatures,
  useTable,
  type ColumnDef,
  type ColumnFiltersState,
  type ExpandedState,
  type PaginationState,
  type Row,
  type RowData,
  type RowSelectionState,
  type SortingState,
} from '@tanstack/react-table'
import {
  CaretDoubleLeft,
  CaretDoubleRight,
  CaretDown,
  CaretLeft,
  CaretRight,
  CaretUp,
  CaretUpDown,
  Columns,
  FadersHorizontal,
  MagnifyingGlass,
  Rows,
  X,
} from '@phosphor-icons/react'
import { cn } from 'cn'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Input } from '@/components/ui/input'
import { Popover } from '@/components/ui/popover'
import { SegmentedControl, type SegmentedOption } from '@/components/ui/segmented-control'
import { Select } from '@/components/ui/select'
import { Tile } from '@/components/ui/tile'
import { PRESS_CLASS } from '@/lib/motion'
import { TILE_THEMES, type TileTone } from '@/lib/tokens'

// ============================================================================
// TanStack Table v9 Feature Bundle & Typed Helpers
// ============================================================================

export type TableDensity = 'compact' | 'comfortable' | 'spacious'

export interface GlazeColumnMeta {
  /** Horizontal text alignment for header and cells */
  align?: 'left' | 'center' | 'right'
  /** Human-readable column label shown in the column visibility menu */
  label?: string
  /** Extra classes applied to the header <th> */
  headerClassName?: string
  /** Extra classes applied to each body <td> */
  cellClassName?: string
  /** Apply tabular-nums & monospace-friendly alignment for numeric values */
  numeric?: boolean
}

/**
 * Static TanStack Table v9 feature set powering Glaze DataTable.
 * Includes sorting, global & column filtering, pagination, row selection,
 * row expansion, and column visibility with typed columnMeta.
 */
export const glazeTableFeatures = tableFeatures({
  columnVisibilityFeature,
  columnFilteringFeature,
  globalFilteringFeature,
  rowSortingFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  rowExpandingFeature,
  filteredRowModel: createFilteredRowModel(),
  sortedRowModel: createSortedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  expandedRowModel: createExpandedRowModel(),
  filterFns: {
    includesString: filterFn_includesString,
    equalsString: filterFn_equalsString,
    equals: filterFn_equals,
    arrIncludesSome: filterFn_arrIncludesSome,
    inNumberRange: filterFn_inNumberRange,
  },
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
    basic: sortFn_basic,
    datetime: sortFn_datetime,
  },
  columnMeta: {} as GlazeColumnMeta,
})

export type GlazeTableFeatures = typeof glazeTableFeatures

export type DataTableColumnDef<TData extends RowData, TValue = unknown> = ColumnDef<
  GlazeTableFeatures,
  TData,
  TValue
>

export type DataTableRow<TData extends RowData> = Row<GlazeTableFeatures, TData>

/**
 * Create a strongly-typed TanStack Table v9 column helper pre-bound to Glaze features.
 */
export function createGlazeColumnHelper<TData extends RowData>() {
  return createColumnHelper<GlazeTableFeatures, TData>()
}

// ============================================================================
// Layer 1: Semantic Styled Table Primitives
// ============================================================================

const DENSITY_CELL_PADDING: Record<TableDensity, string> = {
  compact: 'py-2 px-3',
  comfortable: 'py-3 px-3.5',
  spacious: 'py-4 px-4',
}

const DENSITY_HEAD_PADDING: Record<TableDensity, string> = {
  compact: 'py-2 px-3',
  comfortable: 'py-2.5 px-3.5',
  spacious: 'py-3 px-4',
}

const TableDensityContext = React.createContext<TableDensity>('comfortable')

export interface TableProps extends React.TableHTMLAttributes<HTMLTableElement> {
  /** Row vertical padding density */
  density?: TableDensity
  /** Sticky table header when scrolled vertically */
  stickyHeader?: boolean
  /** Extra classes on the scrollable container */
  containerClassName?: string
}

export const Table = React.forwardRef<HTMLTableElement, TableProps>(function Table(
  { density = 'comfortable', stickyHeader = false, containerClassName, className, ...props },
  ref,
) {
  return (
    <TableDensityContext.Provider value={density}>
      <div
        className={cn(
          'w-full overflow-x-auto',
          stickyHeader && 'max-h-[540px] overflow-y-auto',
          containerClassName,
        )}
      >
        <table
          ref={ref}
          data-density={density}
          className={cn(
            'w-full border-collapse text-left text-[13.5px] text-[#1B1F27] tabular-nums',
            className,
          )}
          {...props}
        />
      </div>
    </TableDensityContext.Provider>
  )
})

export const TableHeader = React.forwardRef<
  HTMLTableSectionElement,
  React.HTMLAttributes<HTMLTableSectionElement>
>(function TableHeader({ className, ...props }, ref) {
  return (
    <thead
      ref={ref}
      className={cn('text-[12px] font-semibold text-[#6B7280]', className)}
      {...props}
    />
  )
})

export const TableBody = React.forwardRef<
  HTMLTableSectionElement,
  React.HTMLAttributes<HTMLTableSectionElement>
>(function TableBody({ className, ...props }, ref) {
  return <tbody ref={ref} className={cn('divide-y divide-[#F2F3F5]', className)} {...props} />
})

