import * as React from 'react'
import {
  CartesianGrid,
  Line,
  LineChart as RechartsLineChart,
  ReferenceLine,
  XAxis,
  YAxis,
} from 'recharts'
import { cn } from 'cn'
import type { Hue, TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  resolveSeriesColor,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface LineSeries {
  dataKey: string
  label?: string
  color?: string
  hue?: Hue
  unit?: string
  dashed?: boolean
  strokeDasharray?: string
  strokeWidth?: number
  showDots?: boolean
}

export interface LineChartProps {
  data: readonly object[]
  xKey: string
  series: LineSeries[]
  config?: ChartConfig
  tone?: TileTone
  height?: number | string
  curve?: 'monotone' | 'natural' | 'linear' | 'step' | 'stepAfter'
  showGrid?: boolean
  showXAxis?: boolean
  showYAxis?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  interactiveLegend?: boolean
  showDots?: boolean
  connectNulls?: boolean
  referenceLine?: { y: number; label?: string; color?: string }
  xAxisTicks?: (string | number)[]
  xTickFormatter?: (value: unknown) => string
  yTickFormatter?: (value: unknown) => string
  valueFormatter?: (value: number | string, name?: string) => React.ReactNode
  labelFormatter?: (label: React.ReactNode) => React.ReactNode
  yDomain?: [number | 'auto' | 'dataMin' | 'dataMax', number | 'auto' | 'dataMin' | 'dataMax']
  yAxisWidth?: number | 'auto'
  margin?: { top?: number; right?: number; bottom?: number; left?: number }
  animate?: boolean
  className?: string
}

export function LineChart({
  data,
  xKey,
  series,
  config,
  tone,
  height = 220,
  curve = 'monotone',
  showGrid = true,
  showXAxis = true,
  showYAxis = false,
  showTooltip = true,
  showLegend = false,
  interactiveLegend = true,
  showDots = false,
  connectNulls = true,
  referenceLine,
  xAxisTicks,
  xTickFormatter,
  yTickFormatter,
  valueFormatter,
  labelFormatter,
  yDomain,
  yAxisWidth = 'auto',
  margin,
  animate = true,
  className,
}: LineChartProps) {
  const theme = useChartTheme(tone)
  const [hiddenKeys, setHiddenKeys] = React.useState<Set<string>>(() => new Set())

  const resolvedSeries = React.useMemo(
    () =>
      series.map((s, idx) => ({
        ...s,
        resolvedColor: resolveSeriesColor(s.dataKey, idx, config, s.color, s.hue),
        resolvedLabel: s.label ?? config?.[s.dataKey]?.label ?? s.dataKey,
      })),
    [series, config],
  )

  const mergedConfig = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = { ...config }
    resolvedSeries.forEach((s) => {
      out[s.dataKey] = {
        ...out[s.dataKey],
        label: s.resolvedLabel,
        color: s.resolvedColor,
        unit: s.unit ?? out[s.dataKey]?.unit,
      }
    })
    return out
  }, [config, resolvedSeries])

  const toggleKey = React.useCallback((key: string) => {
    setHiddenKeys((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])

  const chartMargin = {
    top: margin?.top ?? 8,
    right: margin?.right ?? 12,
    bottom: margin?.bottom ?? (showXAxis ? 0 : 4),
    left: margin?.left ?? (showYAxis ? 4 : showXAxis ? 12 : 4),
  }

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-2.5', className)}>
      {showLegend && (
        <ChartLegend
          tone={tone}
          items={resolvedSeries.map((s) => ({
            key: s.dataKey,
            label: s.resolvedLabel,
            color: s.resolvedColor,
            dashed: s.dashed || Boolean(s.strokeDasharray),
          }))}
          hiddenKeys={interactiveLegend ? hiddenKeys : undefined}
          onToggleKey={interactiveLegend ? toggleKey : undefined}
        />
      )}
      <ChartContainer
        config={mergedConfig}
        tone={tone}
        height={height}
        className="w-full"
      >
        <RechartsLineChart data={data} margin={chartMargin}>
          {showGrid && (
            <CartesianGrid
              vertical={false}
              stroke={theme.gridColor}
              strokeDasharray="3 4"
            />
          )}

          {showXAxis && (
            <XAxis
              dataKey={xKey}
              ticks={xAxisTicks}
              axisLine={false}
              tickLine={false}
              tickMargin={8}
              padding={{ left: 6, right: 6 }}
              tick={{ fill: theme.axisColor }}
              tickFormatter={xTickFormatter ? (v) => xTickFormatter(v) : undefined}
            />
          )}

          {(showYAxis || Boolean(referenceLine)) && (
            <YAxis
              hide={!showYAxis}
              width={yAxisWidth}
              domain={
                yDomain ??
                (referenceLine
                  ? [0, (dataMax: number) => Math.max(dataMax, Math.ceil(referenceLine.y * 1.12))]
                  : undefined)
              }
              axisLine={false}
              tickLine={false}
              tickMargin={6}
              tick={{ fill: theme.axisColor }}
              tickFormatter={yTickFormatter ? (v) => yTickFormatter(v) : undefined}
            />
          )}

          {referenceLine && (
            <ReferenceLine
              y={referenceLine.y}
              ifOverflow="extendDomain"
              stroke={referenceLine.color ?? theme.cursorStroke}
              strokeDasharray="4 4"
              strokeWidth={1.5}
              label={
                referenceLine.label
                  ? {
                      value: referenceLine.label,
                      position: 'insideTopRight',
                      fill: referenceLine.color ?? theme.axisColor,
                      fontSize: 11,
                      fontWeight: 600,
                    }
                  : undefined
              }
            />
          )}

          {showTooltip && (
            <ChartTooltip
              cursor={{
                stroke: theme.cursorStroke,
                strokeWidth: 1.25,
                strokeDasharray: '4 4',
              }}
              content={(tooltipProps) => (
                <ChartTooltipContent
                  active={tooltipProps.active}
                  payload={tooltipProps.payload}
                  label={tooltipProps.label}
                  valueFormatter={valueFormatter}
                  labelFormatter={labelFormatter}
                />
              )}
            />
          )}

          {resolvedSeries.map((s) => {
            if (hiddenKeys.has(s.dataKey)) return null
            const dotsEnabled = s.showDots ?? showDots
            return (
              <Line
                key={s.dataKey}
                type={curve}
                dataKey={s.dataKey}
                name={String(s.resolvedLabel)}
                stroke={s.resolvedColor}
                strokeWidth={s.strokeWidth ?? 2.5}
                strokeDasharray={s.strokeDasharray ?? (s.dashed ? '5 4' : undefined)}
                strokeLinecap="round"
                strokeLinejoin="round"
                connectNulls={connectNulls}
                dot={
                  dotsEnabled
                    ? { r: 3.5, fill: theme.tile.bg, stroke: s.resolvedColor, strokeWidth: 2 }
                    : false
                }
                activeDot={{
                  r: 4.5,
                  fill: s.resolvedColor,
                  stroke: theme.tile.bg,
                  strokeWidth: 2,
                }}
                isAnimationActive={animate}
                animationDuration={CHART_ANIMATION_DURATION}
                animationEasing={CHART_ANIMATION_EASING}
              />
            )
          })}
        </RechartsLineChart>
      </ChartContainer>
    </div>
  )
}

bar-chart.sourceCode:
import * as React from 'react'
import {
  Bar,
  BarChart as RechartsBarChart,
  CartesianGrid,
  Rectangle,
  ReferenceLine,
  XAxis,
  YAxis,
  type BarShapeProps,
} from 'recharts'
import { cn } from 'cn'
import type { Hue, TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  resolveSeriesColor,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface BarSeries {
  dataKey: string
  label?: string
  color?: string
  hue?: Hue
  unit?: string
  /** Optional muted color for non-highlighted bars when using highlightKey or highlightIndex */
  mutedColor?: string
}

export interface BarChartProps {
  data: readonly object[]
  xKey: string
  series: BarSeries[]
  config?: ChartConfig
  tone?: TileTone
  height?: number | string
  /** 'vertical' renders upright columns; 'horizontal' renders left-to-right bars */
  orientation?: 'vertical' | 'horizontal'
  stacked?: boolean
  barSize?: number
  barGap?: number
  barCategoryGap?: number | string
  radius?: number | [number, number, number, number]
  /** Boolean property on each data item to highlight that bar (other bars use mutedColor) */
  highlightKey?: string
  /** Index of a single bar to highlight (other bars use mutedColor) */
  highlightIndex?: number
  showGrid?: boolean
  showXAxis?: boolean
  showYAxis?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  interactiveLegend?: boolean
  referenceLine?: { value: number; label?: string; color?: string }
  xTickFormatter?: (value: unknown) => string
  yTickFormatter?: (value: unknown) => string
  valueFormatter?: (value: number | string, name?: string) => React.ReactNode
  labelFormatter?: (label: React.ReactNode) => React.ReactNode
  yAxisWidth?: number | 'auto'
  margin?: { top?: number; right?: number; bottom?: number; left?: number }
  animate?: boolean
  className?: string
}

export function BarChart({
  data,
  xKey,
  series,
  config,
  tone,
  height = 220,
  orientation = 'vertical',
  stacked = false,
  barSize,
  barGap = 6,
  barCategoryGap = '22%',
  radius,
  highlightKey,
  highlightIndex,
  showGrid = true,
  showXAxis = true,
  showYAxis = false,
  showTooltip = true,
  showLegend = false,
  interactiveLegend = true,
  referenceLine,
  xTickFormatter,
  yTickFormatter,
  valueFormatter,
  labelFormatter,
  yAxisWidth = 'auto',
  margin,
  animate = true,
  className,
}: BarChartProps) {
  const theme = useChartTheme(tone)
  const [hiddenKeys, setHiddenKeys] = React.useState<Set<string>>(() => new Set())
  const isHorizontal = orientation === 'horizontal'

  const resolvedSeries = React.useMemo(
    () =>
      series.map((s, idx) => ({
        ...s,
        resolvedColor: resolveSeriesColor(s.dataKey, idx, config, s.color, s.hue),
        resolvedLabel: s.label ?? config?.[s.dataKey]?.label ?? s.dataKey,
      })),
    [series, config],
  )

  const mergedConfig = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = { ...config }
    resolvedSeries.forEach((s) => {
      out[s.dataKey] = {
        ...out[s.dataKey],
        label: s.resolvedLabel,
        color: s.resolvedColor,
        unit: s.unit ?? out[s.dataKey]?.unit,
      }
    })
    return out
  }, [config, resolvedSeries])

  const toggleKey = React.useCallback((key: string) => {
    setHiddenKeys((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])

  const visibleSeries = resolvedSeries.filter((s) => !hiddenKeys.has(s.dataKey))

  const chartMargin = {
    top: margin?.top ?? 8,
    right: margin?.right ?? 10,
    bottom: margin?.bottom ?? (showXAxis ? 0 : 4),
    left: margin?.left ?? 4,
  }

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-2.5', className)}>
      {showLegend && (
        <ChartLegend
          tone={tone}
          items={resolvedSeries.map((s) => ({
            key: s.dataKey,
            label: s.resolvedLabel,
            color: s.resolvedColor,
          }))}
          hiddenKeys={interactiveLegend ? hiddenKeys : undefined}
          onToggleKey={interactiveLegend ? toggleKey : undefined}
        />
      )}
      <ChartContainer
        config={mergedConfig}
        tone={tone}
        height={height}
        className="w-full"
      >
        <RechartsBarChart
          data={data}
          layout={isHorizontal ? 'vertical' : 'horizontal'}
          barGap={barGap}
          barCategoryGap={barCategoryGap}
          margin={chartMargin}
        >
          {showGrid && (
            <CartesianGrid
              vertical={isHorizontal}
              horizontal={!isHorizontal}
              stroke={theme.gridColor}
              strokeDasharray="3 4"
            />
          )}

          {isHorizontal ? (
            <>
              <XAxis
                type="number"
                hide={!showXAxis}
                domain={[0, 'auto']}
                axisLine={false}
                tickLine={false}
                tickMargin={8}
                tick={{ fill: theme.axisColor }}
                tickFormatter={xTickFormatter ? (v) => xTickFormatter(v) : undefined}
              />
              {showYAxis && (
                <YAxis
                  type="category"
                  dataKey={xKey}
                  width={yAxisWidth}
                  axisLine={false}
                  tickLine={false}
                  tickMargin={6}
                  tick={{ fill: theme.axisColor }}
                  tickFormatter={yTickFormatter ? (v) => yTickFormatter(v) : undefined}
                />
              )}
            </>
          ) : (
            <>
              {showXAxis && (
                <XAxis
                  dataKey={xKey}
                  axisLine={false}
                  tickLine={false}
                  tickMargin={8}
                  tick={{ fill: theme.axisColor }}
                  tickFormatter={xTickFormatter ? (v) => xTickFormatter(v) : undefined}
                />
              )}
              {showYAxis && (
                <YAxis
                  width={yAxisWidth}
                  axisLine={false}
                  tickLine={false}
                  tickMargin={6}
                  tick={{ fill: theme.axisColor }}
                  tickFormatter={yTickFormatter ? (v) => yTickFormatter(v) : undefined}
                />
              )}
            </>
          )}

          {referenceLine && (
            <ReferenceLine
              x={isHorizontal ? referenceLine.value : undefined}
              y={!isHorizontal ? referenceLine.value : undefined}
              stroke={referenceLine.color ?? theme.cursorStroke}
              strokeDasharray="4 4"
              strokeWidth={1.5}
              label={
                referenceLine.label
                  ? {
                      value: referenceLine.label,
                      position: 'insideTopRight',
                      fill: referenceLine.color ?? theme.axisColor,
                      fontSize: 11,
                      fontWeight: 600,
                    }
                  : undefined
              }
            />
          )}

          {showTooltip && (
            <ChartTooltip
              cursor={{ fill: theme.cursorFill, radius: 8 }}
              content={(tooltipProps) => (
                <ChartTooltipContent
                  active={tooltipProps.active}
                  payload={tooltipProps.payload}
                  label={tooltipProps.label}
                  valueFormatter={valueFormatter}
                  labelFormatter={labelFormatter}
                />
              )}
            />
          )}

          {visibleSeries.map((s, visIdx) => {
            const isTopOfStack = stacked && visIdx === visibleSeries.length - 1
            const isBottomOfStack = stacked && visIdx === 0
            const computedRadius: number | [number, number, number, number] =
              radius !== undefined
                ? radius
                : stacked
                  ? isHorizontal
                    ? isTopOfStack
                      ? [0, 7, 7, 0]
                      : isBottomOfStack
                        ? [7, 0, 0, 7]
                        : [0, 0, 0, 0]
                    : isTopOfStack
                      ? [7, 7, 0, 0]
                      : isBottomOfStack
                        ? [0, 0, 4, 4]
                        : [0, 0, 0, 0]
                  : isHorizontal
                    ? [4, 8, 8, 4]
                    : [8, 8, 3, 3]

            const usePerBarFill =
              highlightKey !== undefined ||
              highlightIndex !== undefined ||
              data.some((d) => typeof (d as Record<string, unknown>).fill === 'string')

            return (
              <Bar
                key={s.dataKey}
                dataKey={s.dataKey}
                name={String(s.resolvedLabel)}
                stackId={stacked ? 'glaze-bar-stack' : undefined}
                fill={s.resolvedColor}
                barSize={barSize}
                radius={computedRadius}
                shape={
                  usePerBarFill
                    ? (barProps: BarShapeProps) => {
                        const payload = barProps.payload as Record<string, unknown> | undefined
                        const idx = barProps.index
                        let fillColor = s.resolvedColor
                        if (typeof payload?.fill === 'string') {
                          fillColor = payload.fill
                        } else if (highlightKey !== undefined) {
                          fillColor = payload?.[highlightKey]
                            ? s.resolvedColor
                            : (s.mutedColor ?? theme.tile.mutedBar)
                        } else if (highlightIndex !== undefined) {
                          fillColor =
                            idx === highlightIndex
                              ? s.resolvedColor
                              : (s.mutedColor ?? theme.tile.mutedBar)
                        }
                        return <Rectangle {...barProps} fill={fillColor} />
                      }
                    : undefined
                }
                isAnimationActive={animate}
                animationDuration={CHART_ANIMATION_DURATION}
                animationEasing={CHART_ANIMATION_EASING}
              />
            )
          })}
        </RechartsBarChart>
      </ChartContainer>
    </div>
  )
}

pie-chart.sourceCode:
import * as React from 'react'
import {
  Pie,
  PieChart as RechartsPieChart,
} from 'recharts'
import { cn } from 'cn'
import { DATAVIZ_PALETTES, HUE_PALETTES, type Hue, type TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface PieChartItem {
  name: string
  value: number
  color?: string
  hue?: Hue
  display?: string
}

export interface PieChartProps {
  data: PieChartItem[]
  variant?: 'donut' | 'pie'
  tone?: TileTone
  height?: number | string
  innerRadius?: number | string
  outerRadius?: number | string
  paddingAngle?: number
  cornerRadius?: number
  centerValue?: React.ReactNode
  centerLabel?: React.ReactNode
  showTooltip?: boolean
  showLegend?: boolean
  valueFormatter?: (value: number | string, name?: string) => React.ReactNode
  animate?: boolean
  className?: string
}

export function PieChart({
  data,
  variant = 'donut',
  tone,
  height = 220,
  innerRadius,
  outerRadius = '88%',
  paddingAngle,
  cornerRadius,
  centerValue,
  centerLabel,
  showTooltip = true,
  showLegend = false,
  valueFormatter,
  animate = true,
  className,
}: PieChartProps) {
  const theme = useChartTheme(tone)
  const isDonut = variant === 'donut'

  const resolvedData = React.useMemo(
    () =>
      data.map((item, idx) => ({
        ...item,
        fill:
          item.color ??
          (item.hue ? HUE_PALETTES[item.hue][500] : undefined) ??
          DATAVIZ_PALETTES.categorical[idx % DATAVIZ_PALETTES.categorical.length],
      })),
    [data],
  )

  const config = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = {}
    resolvedData.forEach((d) => {
      out[d.name] = { label: d.name, color: d.fill }
    })
    return out
  }, [resolvedData])

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-3', className)}>
      <div className="relative w-full" style={{ height }}>
        <ChartContainer config={config} tone={tone} height="100%">
          <RechartsPieChart>
            {showTooltip && (
              <ChartTooltip
                content={(tooltipProps) => (
                  <ChartTooltipContent
                    active={tooltipProps.active}
                    payload={tooltipProps.payload}
                    label={tooltipProps.label}
                    hideLabel
                    valueFormatter={valueFormatter}
                  />
                )}
              />
            )}
            <Pie
              data={resolvedData}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              startAngle={90}
              endAngle={-270}
              innerRadius={innerRadius ?? (isDonut ? '65%' : 0)}
              outerRadius={outerRadius}
              paddingAngle={paddingAngle ?? (isDonut ? 3 : 1.5)}
              cornerRadius={cornerRadius ?? (isDonut ? 6 : 3)}
              stroke="none"
              isAnimationActive={animate}
              animationDuration={CHART_ANIMATION_DURATION}
              animationEasing={CHART_ANIMATION_EASING}
            />
          </RechartsPieChart>
        </ChartContainer>

        {isDonut && (centerValue !== undefined || centerLabel !== undefined) && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
            {centerValue !== undefined && (
              <span
                className="font-glaze-display text-[28px] leading-8 font-extrabold tracking-[-0.02em]"
                style={{ color: theme.tile.ink }}
              >
                {centerValue}
              </span>
            )}
            {centerLabel !== undefined && (
              <span className="mt-0.5 text-[12px] font-medium" style={{ color: theme.axisColor }}>
                {centerLabel}
              </span>
            )}
          </div>
        )}
      </div>

      {showLegend && (
        <ChartLegend
          tone={tone}
          align="center"
          items={resolvedData.map((d) => ({
            key: d.name,
            label: d.name,
            color: d.fill,
          }))}
        />
      )}
    </div>
  )
}

export function DonutChart(props: Omit<PieChartProps, 'variant'>) {
  return <PieChart {...props} variant="donut" />
}

